node --input-type=module -e "
import { loadEnv, botToken } from './src/config.mjs';
import { makeFetchJson } from './src/discordApi.mjs';
import { createAckReactor } from './src/ackReact.mjs';

const CHANNEL = '1520665313631408251';
const MSG = '1533625350892818442';

const env = await loadEnv();
const tok = botToken(env);
if (!tok) throw new Error('missing AVA_DISCORD_BOT_TOKEN');
const fetchJson = makeFetchJson(tok);
const ack = createAckReactor({ fetchJson });

const msg = await fetchJson('/channels/' + CHANNEL + '/messages/' + MSG);
const around = await fetchJson('/channels/' + CHANNEL + '/messages?around=' + MSG + '&limit=8');

const soft = await ack.reactSeen(CHANNEL, MSG);
console.log(JSON.stringify({
  softAck: soft,
  target: {
    id: msg.id,
    author: { id: msg.author?.id, username: msg.author?.username, global_name: msg.author?.global_name, bot: msg.author?.bot },
    content: msg.content,
    timestamp: msg.timestamp,
    referenced: msg.referenced_message ? {
      id: msg.referenced_message.id,
      author: msg.referenced_message.author?.username,
      content: msg.referenced_message.content?.slice(0, 500),
    } : null,
    mentions: (msg.mentions || []).map(m => ({ id: m.id, username: m.username })),
    reactions: (msg.reactions || []).map(r => ({ emoji: r.emoji?.name, count: r.count })),
  },
  nearby: (around || []).map(m => ({
    id: m.id,
    author: m.author?.username,
    content: (m.content || '').slice(0, 400),
    ts: m.timestamp,
  })),
}, null, 2));
"

node --input-type=module -e "
import { loadEnv, botToken } from './src/config.mjs';
import { makeFetchJson } from './src/discordApi.mjs';
import { createAckReactor } from './src/ackReact.mjs';
import { buildHostSiteHourlyBlock } from './src/hostSite.mjs';
import { buildOpsPowerStatusReply } from './src/opsPowerStatus.mjs';
import fs from 'node:fs';

const CHANNEL = '1520665313631408251';
const MSG = '1533625350892818442';
const AUTHOR = '1497037418979786823';

const env = await loadEnv();
const tok = botToken(env);
const fetchJson = makeFetchJson(tok);
const ack = createAckReactor({ fetchJson });
await ack.reactWriting(CHANNEL, MSG);

const [host, power] = await Promise.all([
  buildHostSiteHourlyBlock({ refreshPower: true }),
  buildOpsPowerStatusReply({ authorId: AUTHOR, question: 'update me on weather and power' }),
]);

// Combine: weather from host block + power details (skip duplicate council if we want lean)
// For weather+power ask, host block is the right primary; add bank mood line from power.
const content = [
  'on it — live pack just now.',
  '',
  host.content,
  '',
  '— Ava',
].join('\\n');

fs.writeFileSync('_tmp-weather-power-reply.txt', content, 'utf8');
console.log('---REPLY---');
console.log(content);
console.log('---PAYLOAD SNAP---');
console.log(JSON.stringify({
  batteryPct: host.payload?.solar?.batteryPct,
  weatherOk: host.payload?.weather?.ok,
  period: host.payload?.weather?.period,
  alerts: host.payload?.weather?.alerts?.length,
  morningAvgW: host.payload?.solar?.morningAvgW,
}, null, 2));
"

node --input-type=module -e "
import fs from 'node:fs';
import { loadEnv, botToken } from './src/config.mjs';
import { makeFetchJson } from './src/discordApi.mjs';
import { createAckReactor } from './src/ackReact.mjs';
import { buildHostSiteHourlyBlock } from './src/hostSite.mjs';
import { postAvaDiscord } from './src/avaPost.mjs';

const CHANNEL = '1520665313631408251';
const MSG = '1533625350892818442';

const env = await loadEnv();
const tok = botToken(env);
const fetchJson = makeFetchJson(tok);
const ack = createAckReactor({ fetchJson });

const host = await buildHostSiteHourlyBlock({ refreshPower: true });
const content = [
  'on it — live pack just now.',
  '',
  host.content,
  '',
  '— Ava',
].join('\n');

fs.writeFileSync('_tmp-weather-power-reply.txt', content, 'utf8');

const msg = await postAvaDiscord({
  channelId: CHANNEL,
  content,
  refId: MSG,
  kind: 'operator_directed',
  source: 'phase-msg-weather-power',
});
await ack.clearWriting(CHANNEL, MSG);
console.log('posted', msg?.id, 'author', msg?.author?.id, msg?.author?.username);
"
